create table if not exists public.campagne_visuels_formats(id bigserial primary key,campagne_id bigint not null references public.campagnes_maitres(id) on delete cascade,phase text,nom_visuel text not null,code_visuel text,format_support text not null,quantite_prevue integer default 0,quantite_installee integer default 0,actif boolean default true,instructions_terrain text,created_at timestamptz default now(),updated_at timestamptz default now(),unique(campagne_id,phase,nom_visuel,format_support));
create table if not exists public.support_photos(id bigserial primary key,support_id text not null,campagne_id bigint references public.campagnes_maitres(id),visuel_id bigint references public.campagne_visuels_formats(id),type_photo text,nom_fichier text not null,storage_path text not null,photo_url text,thumbnail_url text,prise_le timestamptz default now(),utilisateur text,statut_validation text default 'À valider',created_at timestamptz default now());
alter table public.infrastructures add column if not exists visuel_id bigint,add column if not exists phase_campagne text,add column if not exists format_visuel text,add column if not exists photo_principale_url text,add column if not exists photo_miniature_url text;
insert into storage.buckets(id,name,public)values('support-photos','support-photos',true)on conflict(id)do update set public=true;
alter table public.campagne_visuels_formats enable row level security;alter table public.support_photos enable row level security;
drop policy if exists cvf_dev on public.campagne_visuels_formats;create policy cvf_dev on public.campagne_visuels_formats for all to public using(true)with check(true);
drop policy if exists sp_dev on public.support_photos;create policy sp_dev on public.support_photos for all to public using(true)with check(true);
drop policy if exists sp_storage_read on storage.objects;create policy sp_storage_read on storage.objects for select to public using(bucket_id='support-photos');
drop policy if exists sp_storage_insert on storage.objects;create policy sp_storage_insert on storage.objects for insert to public with check(bucket_id='support-photos');
grant select,insert,update,delete on public.campagne_visuels_formats,public.support_photos to anon,authenticated;grant usage,select on sequence public.campagne_visuels_formats_id_seq,public.support_photos_id_seq to anon,authenticated;
create or replace function public.list_public_schema_fields()returns table(table_name text,column_name text,data_type text)language sql security definer set search_path=public,information_schema as $$select c.table_name::text,c.column_name::text,c.data_type::text from information_schema.columns c where c.table_schema='public' order by c.table_name,c.ordinal_position$$;grant execute on function public.list_public_schema_fields()to anon,authenticated;
create or replace function public.appliquer_visuel_support(p_support_id text,p_visuel_id bigint,p_utilisateur text default null,p_photo_url text default null,p_photo_path text default null)returns jsonb language plpgsql security definer set search_path=public as $$declare v public.campagne_visuels_formats%rowtype;declare c public.campagnes_maitres%rowtype;declare f text;declare op uuid:=gen_random_uuid();begin select*into v from public.campagne_visuels_formats where id=p_visuel_id and actif=true;if not found then raise exception 'Visuel introuvable.';end if;select*into c from public.campagnes_maitres where id=v.campagne_id and publiee_terrain=true;if not found then raise exception 'Campagne non publiée.';end if;select coalesce(format_affichage,format,type_support)into f from public.infrastructures where support_id=p_support_id for update;if not found then raise exception 'Support introuvable.';end if;if lower(trim(coalesce(f,'')))<>lower(trim(v.format_support))then raise exception 'Format incompatible: % vs %',v.format_support,f;end if;update public.infrastructures set campagne_actuelle=c.nom_campagne,campagne_selon_visuel=c.nom_campagne,visuel_campagne=v.nom_visuel,visuel_en_expo=v.nom_visuel,visuel_id=v.id,phase_campagne=v.phase,format_visuel=v.format_support,edt_associe=coalesce(c.no_edt,edt_associe),photo_principale_url=coalesce(p_photo_url,photo_principale_url),photo_miniature_url=coalesce(p_photo_url,photo_miniature_url),date_derniere_manipulation=now()::text,updated_at=now()where support_id=p_support_id;insert into public.historique_des_campagnes(support_id,campagne,visuel,no_edt,date_installation,photo_installation,utilisateur,raw_data)values(p_support_id,c.nom_campagne,v.nom_visuel,c.no_edt,now()::text,p_photo_url,p_utilisateur,jsonb_build_object('operation_id',op,'phase',v.phase,'format',v.format_support,'photo_path',p_photo_path));update public.campagne_visuels_formats set quantite_installee=quantite_installee+1,updated_at=now()where id=v.id;insert into public.journal_propagations(operation_id,campagne_id,support_id,declencheur,statut,details,utilisateur)values(op,c.id,p_support_id,'Visuel compatible sélectionné','Réussi',jsonb_build_object('visuel',v.nom_visuel,'phase',v.phase,'format',v.format_support),p_utilisateur);return jsonb_build_object('statut','Réussi','campagne',c.nom_campagne,'visuel',v.nom_visuel,'phase',v.phase,'format',v.format_support);end$$;grant execute on function public.appliquer_visuel_support(text,bigint,text,text,text)to anon,authenticated;
create or replace function public.diagnostic_systeme_v07()returns table(check_key text,title text,status text,actual_value text,expected_value text,detail text)language sql security definer set search_path=public as $$select'infrastructures','Infrastructures présentes',case when count(*)=6621 then'OK'else'Avertissement'end,count(*)::text,'6621',(6621-count(*))::text||' manquante(s)'from public.infrastructures union all select'arrets','Arrêts présents',case when count(*)>=4323 then'OK'else'Avertissement'end,count(*)::text,'4323','Total opérationnel'from public.liste_des_arrets union all select'visuels','Visuels configurés',case when count(*)>0 then'OK'else'Avertissement'end,count(*)::text,null,'Les visuels filtrent l’application terrain'from public.campagne_visuels_formats union all select'relations','Relations à confirmer',case when count(*)=0 then'OK'else'Avertissement'end,count(*)::text,'0','À confirmer dans le Studio'from public.relation_rules where validation_status<>'Validée' union all select'photos','Photos orphelines',case when count(*)=0 then'OK'else'Erreur'end,count(*)::text,'0','Support ID inexistant'from public.support_photos p where not exists(select 1 from public.infrastructures i where i.support_id=p.support_id)$$;grant execute on function public.diagnostic_systeme_v07()to anon,authenticated;
